     [DataRow(10.5, "$10.50")]
     [DataRow(0, "$0.00")]
     [DataRow(-5.1, "$-5.10")]
     public void FormatCurrency_VariousAmounts_ReturnsExpected(
         double amount, string expected)
     {
         Assert.AreEqual(expected, _formatter.FormatCurrency((decimal)amount));
     }

     [TestMethod]
     public void FormatCurrency_Precision_MatchesDecimalFormat()
     {
         var result = _formatter.FormatCurrency(1234.56m, "£");

         Assert.MatchesRegex(@"^£\d+\.\d{2}$", result);
     }
